  jsonb_build_object('source','gilded-coast_content_pack_v1','authored',coalesce((item->>'authored')::boolean,true),
    'tension',(item->>'tension')::numeric,'knowledgeScope',item->>'knowledgeScope','publicDynamic',item->>'publicDynamic')
from gilded_coast_pack cross join lateral jsonb_array_elements(data->'socialConnections') item
