join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000014'::uuid and location.slug=item->>'locationSlug'
on conflict(id) do update set name=excluded.name,event_type=excluded.event_type,category=excluded.category,tone=excluded.tone,
