  array(select jsonb_array_elements_text(coalesce(item->'requiredParticipantSlugs','[]'::jsonb))),
  nullif(item->>'minRelationshipStage',''),item->>'contentLevel',nullif(item->>'minSpiceLevel','')::int,
  array(select jsonb_array_elements_text(coalesce(item->'interactionModes','[]'::jsonb))),true,
  (item->>'minParticipants')::int,(item->>'maxParticipants')::int,
  array(select jsonb_array_elements_text(coalesce(item->'dayparts','[]'::jsonb))),array[item->>'locationSlug'],1,
  coalesce((item->>'cooldownTurns')::int,24),coalesce((item->>'active')::boolean,true),
  jsonb_build_object('source','gilded-coast_content_pack_v1','requiredParticipantSlugs',item->'requiredParticipantSlugs',
    'outcomePolicy',item->>'outcomePolicy','neverDeclareUserAction',true,'neverMutateRelationshipDirectly',true,'closedWorld',true)
from gilded_coast_pack cross join lateral jsonb_array_elements(data->'interactionBeats') item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000014'::uuid and location.slug=item->>'locationSlug'
left join public.together_locations district on district.world_id='10000000-0000-4000-8000-000000000014'::uuid and district.slug=item->>'districtSlug'
on conflict(world_id,slug) do update set title=excluded.title,location_id=excluded.location_id,
  district_location_id=excluded.district_location_id,interaction_type=excluded.interaction_type,seed=excluded.seed,
  affordances=excluded.affordances,topic_tags=excluded.topic_tags,character_tags=excluded.character_tags,
  min_relationship_stage=excluded.min_relationship_stage,content_level=excluded.content_level,min_spice_level=excluded.min_spice_level,
  interaction_modes=excluded.interaction_modes,co_present_required=excluded.co_present_required,
  required_participant_count=excluded.required_participant_count,maximum_participant_count=excluded.maximum_participant_count,
  dayparts=excluded.dayparts,activity_tags=excluded.activity_tags,weight=excluded.weight,cooldown_hours=excluded.cooldown_hours,
  active=excluded.active,metadata=excluded.metadata,updated_at=now();

do $$
declare loc_count int; resident_count int; schedule_count int; edge_count int; arc_count int; fact_count int;
begin
  select count(*) into loc_count from public.together_locations where world_id='10000000-0000-4000-8000-000000000014'::uuid;
  select count(*) into resident_count from public.together_character_world_presence where world_id='10000000-0000-4000-8000-000000000014'::uuid and presence_type='resident';
  select count(*) into schedule_count from public.together_schedule_templates where character_version_id::text like '25000000-0000-4000-8014-%';
  select count(*) into edge_count from public.together_character_relationship_edges where world_id='10000000-0000-4000-8000-000000000014'::uuid;
  select count(*) into arc_count from public.together_story_arc_templates where specific_world_id='10000000-0000-4000-8000-000000000014'::uuid and active;
  select count(*) into fact_count from public.together_world_facts where world_id='10000000-0000-4000-8000-000000000014'::uuid and active;
  if loc_count<>42 or resident_count<>36 or schedule_count<>1646
    or edge_count<>90 or arc_count<>8 or fact_count<>49 then
    raise exception 'Gilded Coast seed count mismatch: places %, residents %, schedules %, edges %, arcs %, facts %',loc_count,resident_count,schedule_count,edge_count,arc_count,fact_count;
  end if;
  if exists(select 1 from public.together_character_versions where id::text like '25000000-0000-4000-8014-%' and character_bible ?| array['privateTruth','adultContinuity','intimateAnatomy','hiddenSexual']) then
    raise exception 'Gilded Coast private character canon leaked into public bible';
  end if;
end $$;

commit;
